/**
 * The predicate system (card_protocol_spec.md §The Predicate System), with notary parameter references.
 *
 * Reference implementation for the enclave's Rust port (`notary-cards`, erratum E28): the conformance vectors in
 * `notary/vectors/cards/` are generated by running this code, and Rust must agree on every case.
 *
 * Evaluation is over the **subject's chain**, subject first: `chain` holds the decrypted cards walked by Stage 3 and
 * `addresses` every chain address including a trusted root that was not fetched.
 *
 * Fail-closed rules (both implementations):
 * - an expression must be an object with exactly one key; anything else is `false`;
 * - unknown leaves, and `code_equals` (meaningful only in `revocation_permissions`), are `false`;
 * - a parameter reference `{ "param": name }` is resolved from the job's signed `parameters`; outside a notary context
 *   (no `parameters`) it is invalid, and the whole predicate is `false`; an unknown name makes that leaf `false`;
 * - regexes match the whole string and are limited to the subset JavaScript and Rust's `regex` crate both support:
 *   lookaround and backreferences make the leaf `false`.
 */

export interface PredicateContext {
  /** Decrypted chain cards, subject first. */
  chain: { address: string; content: Record<string, unknown> }[];
  /** Every chain address, subject first, including a trusted root that was not fetched. */
  addresses: string[];
  /** The notary job's signed `parameters`; present only inside a notary section. */
  parameters?: Record<string, unknown>;
  /** Whether the subject is the holder / issuer of the card the predicate guards (caller-defined). */
  isHolder?: boolean;
  isIssuer?: boolean;
}

class InvalidPredicate extends Error {}

const UNSUPPORTED_REGEX = /\(\?[=!]|\(\?<[=!]|\\[1-9]|\\k</;

export function fullMatch(pattern: string, value: string): boolean {
  if (UNSUPPORTED_REGEX.test(pattern)) return false;
  try {
    return new RegExp(`^(?:${pattern})$`, "u").test(value);
  } catch {
    return false;
  }
}

function resolve(v: unknown, ctx: PredicateContext): { ok: true; value: unknown } | { ok: false } {
  if (v !== null && typeof v === "object" && !Array.isArray(v) && Object.keys(v).length === 1 && "param" in (v as object)) {
    if (ctx.parameters === undefined) throw new InvalidPredicate("parameter reference outside a notary section");
    const name = (v as { param: unknown }).param;
    if (typeof name !== "string" || !Object.prototype.hasOwnProperty.call(ctx.parameters, name)) return { ok: false };
    return { ok: true, value: ctx.parameters[name] };
  }
  return { ok: true, value: v };
}

function evalExpr(expr: unknown, ctx: PredicateContext): boolean {
  if (expr === null || typeof expr !== "object" || Array.isArray(expr)) return false;
  const keys = Object.keys(expr);
  if (keys.length !== 1) return false;
  const op = keys[0]!;
  const raw = (expr as Record<string, unknown>)[op];
  if (op === "any_of" || op === "all_of" || op === "none_of") {
    if (!Array.isArray(raw)) return false;
    const results = raw.map((e) => evalExpr(e, ctx));
    if (op === "any_of") return results.some(Boolean);
    if (op === "all_of") return results.every(Boolean);
    return !results.some(Boolean);
  }
  const r = resolve(raw, ctx);
  if (!r.ok) return false;
  const v = r.value;
  switch (op) {
    case "issued_under_template":
      return typeof v === "string" && ctx.chain[0]?.content["policy_id"] === v;
    case "chain_includes":
      return typeof v === "string" && ctx.addresses.includes(v);
    case "card_field_matches": {
      if (v === null || typeof v !== "object" || Array.isArray(v)) return false;
      const { template, field, regex } = v as Record<string, unknown>;
      if (typeof template !== "string" || typeof field !== "string" || typeof regex !== "string" || Object.keys(v).length !== 3) return false;
      return ctx.chain.some((l) => l.content["policy_id"] === template && typeof l.content[field] === "string" && fullMatch(regex, l.content[field] as string));
    }
    case "is_holder":
      return v === true && ctx.isHolder === true;
    case "is_issuer":
      return v === true && ctx.isIssuer === true;
    case "chain_depth_at_most":
      return typeof v === "number" && Number.isInteger(v) && v >= 0 && ctx.addresses.length <= v;
    default:
      return false; // code_equals (not valid here) and unknown leaves
  }
}

/** Evaluates a predicate. Never throws: an invalid predicate is `false`. */
export function evaluatePredicate(predicate: unknown, ctx: PredicateContext): boolean {
  try {
    return evalExpr(predicate, ctx);
  } catch (e) {
    if (e instanceof InvalidPredicate) return false;
    throw e;
  }
}
